export type WorkspaceKind = "draft" | "review" | "publish";
export type Snapshot = null | boolean | number | string | Snapshot[] | { [key: string]: Snapshot };

export class WorkspaceStore {
  private readonly stores: Record<WorkspaceKind, Map<string, Snapshot>> = {
    draft: new Map(),
    review: new Map(),
    publish: new Map()
  };

  put(kind: WorkspaceKind, id: string, value: Snapshot): void {
    const key = this.key(id, true)!;
    this.stores[kind].set(key, this.clone(value, new Set()));
  }

  get(kind: WorkspaceKind, id: string): Snapshot | undefined {
    const key = this.key(id, false);
    if (key === undefined) return undefined;
    return this.stores[kind].get(key);
  }

  remove(kind: WorkspaceKind, id: string): boolean {
    const key = this.key(id, false);
    return key === undefined ? false : this.stores[kind].delete(key);
  }

  ids(kind: WorkspaceKind): string[] {
    return Array.from(this.stores[kind].keys());
  }

  private key(id: string, throwing: boolean): string | undefined {
    if (typeof id === "string" && id.trim().length > 0) return id.trim();
    if (throwing) throw new TypeError("invalid id");
    return undefined;
  }

  private clone(value: unknown, seen: Set<object>): Snapshot {
    if (value === null || typeof value === "boolean" || typeof value === "string") return value;
    if (typeof value === "number") {
      if (!Number.isFinite(value)) throw new TypeError("invalid number");
      return value;
    }
    if (typeof value !== "object") throw new TypeError("invalid snapshot");
    if (seen.has(value)) throw new TypeError("cyclic snapshot");
    seen.add(value);
    let result: Snapshot;
    if (Array.isArray(value)) {
      result = value.map(item => this.clone(item, seen));
    } else {
      if (Object.getPrototypeOf(value) !== Object.prototype) throw new TypeError("non-plain object");
      const object: { [key: string]: Snapshot } = {};
      for (const [key, item] of Object.entries(value)) object[key] = this.clone(item, seen);
      result = object;
    }
    seen.delete(value);
    return result;
  }
}
