import { WorkspaceStore, type Snapshot } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => unknown, message: string): void {
  try { action(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: expected TypeError`); }
  throw new Error(`${message}: expected throw`);
}

const store = new WorkspaceStore();
const original: Snapshot = { title: 'one', nested: { count: 2 }, list: [true, null, { value: 'x' }] };
store.put('draft', '  item  ', original);
(original as { title: string }).title = 'changed';
((original as { nested: { count: number } }).nested).count = 99;
((original as { list: Snapshot[] }).list).push('added');

equal(store.ids('draft').join(','), 'item', 'id normalized and listed');
const fetched1 = store.get('draft', ' item ') as { title: string; nested: { count: number }; list: Snapshot[] };
equal(fetched1.title, 'one', 'stored top-level object is copied');
equal(fetched1.nested.count, 2, 'stored nested object is copied');
equal(fetched1.list.length, 3, 'stored nested array is copied');
fetched1.title = 'mutated get';
fetched1.nested.count = 500;
fetched1.list.length = 0;
const fetched2 = store.get('draft', 'item') as { title: string; nested: { count: number }; list: Snapshot[] };
equal(fetched2.title, 'one', 'get returns a fresh object clone');
equal(fetched2.nested.count, 2, 'get deeply clones nested objects');
equal(fetched2.list.length, 3, 'get deeply clones arrays');
assert(fetched1 !== fetched2, 'get results do not alias');

store.put('draft', 'second', []);
store.put('draft', 'third', {});
equal(store.ids('draft').join(','), 'item,second,third', 'insertion order');
store.put('draft', ' item ', { replacement: true });
equal(store.ids('draft').join(','), 'item,second,third', 'replacement does not change order');
equal(JSON.stringify(store.get('draft', 'item')), JSON.stringify({ replacement: true }), 'replacement updates snapshot');

store.put('review', 'item', 'review value');
store.put('publish', 'item', 7);
equal(store.get('review', 'item'), 'review value', 'review store independent');
equal(store.get('publish', 'item'), 7, 'publish store independent');
equal(JSON.stringify(store.get('draft', 'item')), JSON.stringify({ replacement: true }), 'draft store independent');

equal(store.get('draft', ''), undefined, 'malformed get returns undefined');
equal(store.get('draft', null as unknown as string), undefined, 'non-string get returns undefined');
equal(store.remove('draft', '   '), false, 'malformed remove returns false');
equal(store.remove('draft', 'missing'), false, 'missing remove returns false');
equal(store.remove('draft', ' second '), true, 'remove normalizes id');
equal(store.remove('draft', 'second'), false, 'removed id no longer exists');
equal(store.ids('draft').join(','), 'item,third', 'remove updates ids');
throwsTypeError(() => store.put('draft', '   ', null), 'malformed put id');
throwsTypeError(() => store.put('draft', null as unknown as string, null), 'non-string put id');

store.put('publish', 'null', null);
store.put('publish', 'false', false);
store.put('publish', 'empty-string', '');
store.put('publish', 'zero', 0);
equal(store.get('publish', 'null'), null, 'null snapshot valid');
equal(store.get('publish', 'false'), false, 'boolean snapshot valid');
equal(store.get('publish', 'empty-string'), '', 'empty string snapshot valid');
equal(store.get('publish', 'zero'), 0, 'finite zero snapshot valid');

const cycle: { self?: unknown } = {};
cycle.self = cycle;
throwsTypeError(() => store.put('draft', 'cycle', cycle as Snapshot), 'cycles rejected');
for (const value of [undefined, () => 1, Symbol('x'), 1n, Number.NaN, Number.POSITIVE_INFINITY, new Date()] as unknown[]) {
  throwsTypeError(() => store.put('draft', 'invalid', value as Snapshot), `invalid root value ${String(value)}`);
}
throwsTypeError(() => store.put('draft', 'nested-invalid', { value: undefined } as unknown as Snapshot), 'nested undefined rejected');
throwsTypeError(() => store.put('draft', 'symbol-invalid', { value: Symbol('x') } as unknown as Snapshot), 'nested symbol rejected');
throwsTypeError(() => store.put('draft', 'null-prototype', Object.create(null) as Snapshot), 'non-plain object rejected');
equal(store.get('draft', 'invalid'), undefined, 'failed validation stores nothing');

